import math

def tau(n):
    """Calculates the total number of divisors of n."""
    if n == 1:
        return 1
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def d_n(n):
    """Calculates the number of positive divisors of n other than 1 and itself."""
    if n <= 1:
        return -1 # Or handle appropriately, d(1) = 0 - 2 = -2 if we strictly follow tau(1)=1. But the problem implies positive integers.
                   # For n=1, divisors are {1}. Divisors other than 1 and itself: none. So d(1) = 0.
                   # tau(1) = 1. d(1) = 1 - 2 = -1. This formula breaks for n=1.
                   # Let's handle n=1 separately: d(1) = 0.
    return tau(n) - 2

# Recalculating d(1) based on definition:
# n=1. Divisors are {1}. Divisors other than 1 and itself: empty set. Size is 0.
def d_n_corrected(n):
    if n <= 1:
        return 0
    return tau(n) - 2

