def check_a1():
    factors = []
    for i in range(1, int(735**0.5) + 1):
        if 735 % i == 0:
            factors.append(i)

    results = []
    for i in range(len(factors)):
        for j in range(i, len(factors)):
            X = factors[i]
            Y = factors[j]
            if X * Y == 735 and X < Y:
                # Check parity: since 735 is odd, X and Y are odd. X+Y is even.
